const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
let ok=true;const t=(c,m)=>{if(!c)ok=false;console.log((c?'PASS ':'FAIL ')+m)};
(async()=>{const b=await chromium.launch();const e=[];
for(const [w,h,n] of [[1440,950,'d'],[390,844,'m']]){const p=await b.newPage({viewport:{width:w,height:h}});p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>localStorage.clear());await p.reload();await p.waitForTimeout(300);await p.click('.lp-hero [data-act="new"]');
t(await p.locator('.modesw [data-mode="explore"][aria-checked="true"]').count()===1,n+': Explore is the default mode');
await p.fill('#start-in','We want team invites so admins can add colleagues. Sales says enterprise deals stall without it. We think simple email invites are enough for v1.');await p.press('#start-in','Enter');
await p.waitForSelector('.m-ai .opts3',{timeout:15000});
t(await p.locator('.m-ai .qcard').count()===0,n+': no form question on the first reply');
t(await p.locator('.m-ai .pcard:not(.done) .yes').count()===0,n+': no accept-each-claim cards');
t((await p.locator('.logged').textContent()).includes('Logged'),n+': claims are logged in one line');
t(await p.locator('.opt3').count()===3,n+': three ways to build v1');
t((await p.locator('.opts3').textContent()).includes('Dropbox')||(await p.locator('.opts3').textContent()).includes('Follow'),n+': options use similar apps for this idea');
t(await p.locator('.unk-row').count()>=2,n+': biggest unknowns listed');
t((await p.locator('.unk').textContent()).includes('simple email invites'),n+': unknowns quote the user\'s own bet');
t(await p.locator('.brief .pv').count()===3,n+': research brief included');
t(await p.locator('.nextq .chip').count()>=3,n+': suggests what to explore next, with a finish chip');
const docN=await p.evaluate(()=>JSON.parse(localStorage.getItem('scopeline-chat-v1')).features[0].doc.length);t(docN>=3,n+': definition filled without clicking ('+docN+')');
await p.locator('.opt3 .yes').first().click();await p.waitForTimeout(200);
t(await p.locator('.opt3.on').count()===1,n+': choosing an option marks it');
const doc=await p.evaluate(()=>JSON.parse(localStorage.getItem('scopeline-chat-v1')).features[0].doc.map(x=>x.kind));t(doc.includes('decision')&&doc.includes('scope_in'),n+': choice recorded as decision and scope');
await p.click('[data-undolog]');await p.waitForTimeout(200);t((await p.locator('.logged').first().textContent()).includes('Removed'),n+': undo removes logged claims');
await p.locator('.nextq .chip').first().click();await p.waitForFunction(()=>document.querySelectorAll('.m-ai').length>=2,null,{timeout:15000});await p.waitForTimeout(700);
t((await p.locator('.m-ai').last().textContent()).toLowerCase().includes('risk'),n+': next chip gets an answer (risks)');
t(await p.locator('.m-ai').last().locator('.qcard').count()===0,n+': still no form question');
await p.locator('.nextq .chip.fin').click();await p.waitForTimeout(300);t(await p.locator('.plan2').count()===1,n+': "I\'m done" finishes in one click');
t(await p.evaluate(()=>document.documentElement.scrollWidth-innerWidth)<=0,n+': no sideways scroll');
await p.screenshot({path:S+'/explore-'+n+'.png',fullPage:false});await p.close();}
t(e.length===0,'no errors '+e.join('; '));console.log(ok?'ALL PASS':'SOME FAIL');await b.close();})();
